    fn sanitize_keeps_question_and_exclaim() {
        assert_eq!(sanitize_title("What is quantum?"), "What is quantum?");
        assert_eq!(sanitize_title("Eureka!"), "Eureka!");
    }

    #[test]
    fn sanitize_takes_first_line_only() {
        assert_eq!(
