function schedulePrune(corpusId: string): void {
  setTimeout(() => {
    const cur = _byCorpus[corpusId];
    if (!cur || cur.terminal === null) return;
    _byCorpus = produce(_byCorpus, (d) => {
      delete d[corpusId];
